TYPES:
PayloadRef = {hash:Str, type:Kw, size:Int, storage:Kw}
MemStore = Map<Str, Bytes>
CausalNode = {id:Str, type:Kw, payload-ref:PayloadRef, meta:Any}
CausalEdge = {from:Str, to:Str, type:Kw}
CausalGraph = {nodes:Set<CausalNode>, edges:Set<CausalEdge>}
ContextNode = {id:Str, type:Kw, content:Str, feedbacks:List<Str>}
PrefillState = {context:List<ContextNode>, target-id:Str, hash:Str}
World = {id:Str, root:Str, head:Str, policy:Kw, meta:Any, lifecycle:Kw}
Registry = {worlds:Map<Str,World>, ancestry:Map<Str,Str>, active-id:Str?, graph:CausalGraph, memory:MemStore}
ObsWorld = {id:Str, root:Str, head:Str, policy:Kw, meta:Any, lifecycle:Kw, parent:Str?}
ObsRegistry = {ids:List<Str>, active:Str?, archived:List<Str>}
ObsAncestry = {child:Str, parent:Str, path:List<Str>}
ObsDiff = {changed:Bool, fields:List<Kw>}

OPS:
store-payload(store:MemStore, content:Str) -> PayloadRef:
  h = SHA256(content)
  store[h] = content
  return {hash:h, type:infer(content), size:len(content), storage:default}

load-payload(store:MemStore, ref:PayloadRef) -> Str:
  return store[ref.hash]

add-node!(graph:CausalGraph, node:CausalNode) -> Void:
  PRE: node.id not in graph.nodes
  graph.nodes += node

add-edge!(graph:CausalGraph, edge:CausalEdge) -> Void:
  PRE: edge.from in graph.nodes AND edge.to in graph.nodes
  graph.edges += edge

causal-subgraph(graph:CausalGraph, target:Str) -> List<CausalNode>:
  return DFS(graph, target, filter=:causal) | sort(root-first)

project-context(graph:CausalGraph, store:MemStore, target:Str, evals:Bool) -> List<ContextNode>:
  nodes = causal-subgraph(graph, target)
  return map(n -> {id:n.id, type:n.type, content:load-payload(store, n.payload-ref), feedbacks:if(evals) get-evals(n) else []})

canonical-prompt(ctx:List<ContextNode>) -> Str:
  return format(ctx)

build-prefill-state(graph:CausalGraph, store:MemStore, target:Str) -> PrefillState:
  ctx = project-context(graph, store, target, false)
  return {context:ctx, target-id:target, hash:SHA256(canonical-prompt(ctx))}

register-world(reg:Registry, world:World) -> Void:
  PRE: world.id not in reg.worlds
  reg.worlds[world.id] = world

set-active-world(reg:Registry, id:Str) -> Void:
  PRE: id in reg.worlds
  reg.active-id = id

archive-world(reg:Registry, id:Str) -> Void:
  w = reg.worlds[id]
  w.lifecycle = :archived
  if(reg.active-id == id) reg.active-id = nil

INVS:
INV: forall(w in Registry.worlds): w.graph == Registry.graph
INV: forall(w in Registry.worlds): w.memory == Registry.memory
INV: count(w in Registry.worlds where w.lifecycle == :active) <= 1
INV: Observation types subset {Str, Num, Kw, Char, List}

TYPES:
PayloadRef = {hash:SHA256, type:Str, size:U64, storage:Ref}
MemStore = HashTable<Str, Payload>
CausalNode = {id:ID, type:Type, payload:PayloadRef, meta:Map}
CausalEdge = {from:ID, to:ID, type:{:causal|:eval}}
CausalGraph = {nodes:[CausalNode], edges:[CausalEdge]}
ContextNode = {id:ID, type:Type, content:Str, feedbacks:[Str]}
PrefillState = {context:[ContextNode], target:ID, hash:SHA256}
World = {id:ID, graph:Ref, mem:Ref, root:ID, head:ID, policy:Map, meta:Map, lifecycle:{:created|:active|:inactive|:archived}}
Registry = {worlds:[World], ancestry:Map<ID,ID>, active:ID, graph:Ref, mem:Ref}
WorldObs = {ver:1, world-id:ID, root-id:ID, head-id:ID, policy:Map, meta:Map, lifecycle:Enum, parent-id:ID}
RegistryObs = {ver:1, world-ids:[ID], active-id:ID, archived-ids:[ID]}
AncestryObs = {world-id:ID, parent-id:ID, path:[ID]}
DiffObs = {changed:Bool, fields:[Str]}

INVARIANTS:
INV(Graph): Unique(node.id)
INV(Mem): ContentAddr(hash=SHA256(content))
INV(World): head in graph.nodes
INV(Commit): Atomic(GraphAppend, HeadAdvance)
INV(Obs): Type(x) in {null, bool, str, num, char, kw, list}
INV(Truth): kernel-commit-world! == ONLY(head_advance)
INV(Replay): Hash(Graph+Mem+Policy) == PrefillHash

OPERATIONS:
make-memory-store() -> MemStore
add-node!(g, n) -> g' | Pre: !exists(g.nodes, n.id)
add-edge!(g, e) -> g' | Pre: exists(g.nodes, e.from) & exists(g.nodes, e.to)
causal-subgraph(g, target) -> [Node] | Filter: edge.type==:causal; Order: Root->Target
project-context(g, m, target, include_eval) -> [ContextNode] | Logic: ancestry->load->ctx; If include_eval: add :EVAL feedbacks
canonical-prompt(ctx) -> PrefillState | Rule: Deterministic
make-world(id, g, m, root, head, policy, meta) -> World | Pre: exists(g.nodes, root), exists(g.nodes, head)
fork-world(parent, child_id) -> World | Post: child.graph==parent.graph, child.mem==parent.mem
replace-world-metadata!(w, meta) -> w' | Post: w'.meta==meta, w'.graph==w.graph (CoW)
kernel-commit-world!(w, node) -> w' | Pre: valid(node); Post: w'.head==node.id, w'.graph.nodes+=[node]
replay-world(w) -> {id, head, policy, meta, hash}
register-world(r, w) -> r' | Pre: unique(w.id), exists(r.worlds, w.parent)
set-active-world(r, id) -> r' | Pre: w.lifecycle!=:archived
archive-world(r, id) -> r' | Post: w.lifecycle=:archived, r.active!=id
snapshot-world(w) -> WorldObs | Rule: Data-only, No mutation
snapshot-registry(r) -> RegistryObs | Rule: Data-only, No mutation
snapshot-ancestry(w) -> AncestryObs | Rule: Data-only, No mutation
snapshot-diff(w1, w2) -> DiffObs | Rule: Data-only, No mutation

TYPE context-node = { id: ID, type: Keyword, content: String, feedbacks: [String] }
OP associated-evaluations(g: Graph, nid: ID) -> [ID]: collect(e.to FOR e IN g.edges IF e.type==`:eval` && e.from==nid) ORDER BY insertion
OP project-context(g: Graph, s: Store, tid: ID, inc_evals: Bool=false) -> [context-node]:
  ancestry = causal-subgraph(g, tid)
  RETURN map(n IN ancestry -> {
    id: n.id, type: n.type, content: load-payload(s, n.payload-ref)||"",
    feedbacks: IF inc_evals THEN [load-payload(s, g.nodes[eid].payload-ref) FOR eid IN associated-evaluations(g, n.id)] ELSE nil
  })
INV project-context -> !mutate(g), !mutate(s), deterministic(inputs)
INV context-node.content == materialized(payload-ref)
